/**
 * GATE L4a-A — THE ENEMY ROSTER IS CONTRACT (lane L4a).
 *
 * `OG_NPCS` is generated by `scripts/payload/transcribeNpcs.py` from the payload's
 * own `npcdata.xml` — never hand-keyed (GAUNTLET.md §2, "a script beats a swarm").
 * This file is the trust, in the same two-part shape `tests/ogItemData.test.ts` and
 * `tests/ogSkillData.test.ts` earned:
 *
 *   1. STRUCTURAL PINS that run everywhere, with no reference payload present.
 *   2. A BYTE-CHECK that re-parses the SOURCE with its own INDEPENDENT grammar —
 *      raw-text regex here, versus ElementTree in the generator — and demands the
 *      committed table match field for field. A shared parser would only prove the
 *      two agree with each other.
 *
 * Grammar facts pinned (probed 2026-09-06/07, re-confirmed 2026-09-08 against
 * npcdata.xml sha256 e9835f3b…30126, 228,413 B):
 *   - 495 <npc> rows; 32 distinct tag names; 35 path-qualified positions; nesting
 *     4 deep; ZERO attributes; ZERO non-ASCII; 9,621 CRLF *and 4 bare LF*.
 *   - FIVE empty leaves, all <mcs></mcs> — npc ids 64, 158, 192, 193, 194. itemdata
 *     had zero, so the item transcriber's "die on an empty tag" rule would kill this
 *     run on legitimate data. Present-but-empty is not absent.
 *   - <lvl> IS AT TWO DEPTHS: 402 are the NPC's own, 647 are a SKILL's rank. 414
 *     rows contain one at some depth, so 12 rows have a skill level and no own level.
 *   - <id> IS AT THREE DEPTHS: npc 495 · reward/loot 131 · skills/skill 647. The
 *     regex parser below must strip BOTH <skills> and <reward> before any scalar read.
 *   - <ai> ABSENT MEANS 1 (`XMLNpc.as:135-141`), not "no AI". 70 rows take that path.
 *   - <mcs> slots are STRINGS: 741 of 3,210 are comma-separated pools that
 *     `processString` (`MCSCharacter.as:573-578`) re-rolls at every spawn, 193 are
 *     exactly '0' (= empty), and 28 lists REPEAT an element, so they are WEIGHTED.
 *   - <scalex>/<scaley> and <chance> are FLOATS (16/16 rows, and 119 of 131).
 *   - TWO source anomalies over 356 occurrences: `6015.6017` (355x — a period where
 *     a comma belongs, and it is in the SHIPPED GAME'S OWN AS3 at `XMLNpc.as:460`)
 *     and `6.5006501650265E+47` (npc 55's <hair>). Both preserved, neither coerced.
 *
 * TWO COINCIDENCE TRAPS, both pinned below as disjoint:
 *   - 5 rows carry NO <name> tag (ids 0, 47, 160, 801, 819); 6 carry a `nameId` the
 *     string table cannot resolve (all the SAME id 5017, npc ids 50-55). "Unnamed"
 *     and "unresolved" are different facts — L3 proved confusing them costs a session.
 *   - 92 rows have no <hp> and 96 rows carry <skills>. Different sets.
 *
 * ⚠️ CORRECTION TO THE L4a RECON (measured 2026-09-08, the source wins). RECON shape 5
 * illustrated "ids are not sorted" with *"807 sits between 197 and 201"*. The real
 * shape is one descent, at source index 209→210: the block of ids 800..819 sits
 * between id 199 and id 200. The claim it illustrated — INDEX IS NOT ID — is correct
 * and is pinned below with the measured neighbours.
 *
 * ⚠️ C2 — these rows are the ANDROID build (v0.682); no web-side artifact
 * corroborates them yet (GAUNTLET.md §2.1).
 */
import { existsSync, readFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';
import { OG_NPCS, OG_NPC_SOURCE_ANOMALIES, type OgNpc } from '../src/config/ogNpcs';

/** How many committed rows carry this field. Absent is ABSENT, never 0. */
const present = (pick: (n: OgNpc) => unknown): number =>
  OG_NPCS.filter((n) => pick(n) !== undefined).length;

/** The 12 paperdoll slots, in EQ INDEX ORDER (GAUNTLET.md §2.2). */
const SLOTS = [
  'armor', 'gloves', 'hair', 'hat', 'head', 'mask',
  'neck', 'pants', 'prop1', 'prop2', 'shoes', 'weapon',
] as const;

const slotValues = (): string[] =>
  OG_NPCS.flatMap((n) => SLOTS.map((s) => n.mcs[s]).filter((v): v is string => v !== undefined));

describe('L4a-A structural pins — run everywhere, no reference payload needed', () => {
  it('carries exactly 495 NPCs, 3,210 paperdoll slots, 647 skills and 131 loot rows', () => {
    expect(OG_NPCS.length).toBe(495);
    expect(slotValues().length).toBe(3210);
    expect(OG_NPCS.reduce((n, r) => n + (r.skills?.length ?? 0), 0)).toBe(647);
    expect(OG_NPCS.reduce((n, r) => n + (r.loot?.length ?? 0), 0)).toBe(131);
    expect(present((n) => n.skills)).toBe(96);
    expect(present((n) => n.loot)).toBe(66);
  });

  it('every npc id is unique, and INDEX IS NOT ID', () => {
    const ids = OG_NPCS.map((n) => n.id);
    expect(new Set(ids).size).toBe(495);
    expect(Math.min(...ids)).toBe(0);
    expect(Math.max(...ids)).toBe(819);
    // Neither sorted nor contiguous: exactly ONE descent, where the 800-block is
    // spliced between ids 199 and 200. Anything keyed on index would read the
    // wrong NPC from here on, so rows are committed in SOURCE ORDER and matched by it.
    const descents = ids.map((v, i) => (i > 0 && v < (ids[i - 1] ?? 0) ? i : -1)).filter((i) => i > 0);
    expect(descents).toEqual([210]);
    expect(ids.slice(207, 213)).toEqual([817, 818, 819, 200, 201, 202]);
    expect(ids.length - new Set(ids).size).toBe(0);
    expect(ids).not.toEqual([...ids].sort((a, b) => a - b));
  });

  it('every field is present on exactly the number of rows the source carries', () => {
    expect(present((n) => n.nameId)).toBe(490);
    expect(present((n) => n.name)).toBe(484);
    expect(present((n) => n.lvl)).toBe(402);
    expect(present((n) => n.hp)).toBe(403);
    expect(present((n) => n.ai)).toBe(425);
    expect(present((n) => n.attack)).toBe(406);
    expect(present((n) => n.defense)).toBe(394);
    expect(present((n) => n.scalex)).toBe(16);
    expect(present((n) => n.scaley)).toBe(16);
    expect(present((n) => n.earth)).toBe(3);
    expect(present((n) => n.fire)).toBe(1);
    // <mcs> is on ALL 495 rows — 5 of them EMPTY. Present-but-empty is not absent.
    expect(present((n) => n.mcs)).toBe(495);
    expect(present((n) => n.aiEffective)).toBe(495);
  });

  it('THE `ai` DEFAULT: 70 silent rows are EnemyKnife (ai 1), not "no AI"', () => {
    const silent = OG_NPCS.filter((n) => n.ai === undefined);
    expect(silent.length).toBe(70);
    for (const n of silent) expect(n.aiEffective, `npc ${String(n.id)}`).toBe(1);
    // Where the source DID speak, aiEffective is its word and nothing else.
    for (const n of OG_NPCS) {
      if (n.ai !== undefined) expect(n.aiEffective, `npc ${String(n.id)}`).toBe(n.ai);
    }
    // 56 rows say ai=1 out loud; 70 are silent. 126 dispatch to EnemyKnife, and
    // the two groups must stay tellable apart — that is the whole point of two fields.
    expect(OG_NPCS.filter((n) => n.ai === 1).length).toBe(56);
    expect(OG_NPCS.filter((n) => n.aiEffective === 1).length).toBe(126);
  });

  it('the `ai` value-space is 34 distinct values, and 0/10/15/16 never appear', () => {
    const used = new Set(OG_NPCS.map((n) => n.ai).filter((v): v is number => v !== undefined));
    expect(used.size).toBe(34);
    expect([...used].sort((a, b) => a - b)[0]).toBe(1);
    expect(Math.max(...used)).toBe(37);
    for (const gap of [0, 10, 15, 16]) {
      expect(used.has(gap), `ai ${String(gap)} is dispatched but never used in the data`).toBe(false);
    }
  });

  it('THE EMPTY PAPERDOLLS survive transcription — 5 rows, not 5 missing rows', () => {
    const empty = OG_NPCS.filter((n) => Object.keys(n.mcs).length === 0);
    expect(empty.map((n) => n.id)).toEqual([64, 158, 192, 193, 194]);
    for (const n of empty) expect(n.mcs, `npc ${String(n.id)}`).toEqual({});
  });

  it('`mcs` slots stay VERBATIM STRINGS — 741 pools, 193 empties, never a number', () => {
    const vals = slotValues();
    for (const v of vals) expect(typeof v).toBe('string');
    expect(vals.filter((v) => v.includes(',')).length).toBe(741);
    expect(vals.filter((v) => v === '0').length).toBe(193);
    // Per slot, exactly as the source distributes them.
    const listsPerSlot: Record<string, number> = {};
    for (const s of SLOTS) {
      const n = OG_NPCS.filter((r) => r.mcs[s]?.includes(',') === true).length;
      if (n > 0) listsPerSlot[s] = n;
    }
    expect(listsPerSlot).toEqual({
      armor: 39, hair: 355, hat: 43, head: 11, mask: 72, pants: 30, shoes: 15, weapon: 176,
    });
  });

  it('THE POOLS ARE WEIGHTED — 28 lists repeat an element, and order is load-bearing', () => {
    // `processString` (MCSCharacter.as:574-579) picks uniformly BY INDEX, so a repeat
    // is a probability and de-duplicating (or sorting) silently reweights the roster.
    const lists = slotValues().filter((v) => v.includes(','));
    const withRepeat = lists.filter((v) => {
      const parts = v.split(',');
      return new Set(parts).size !== parts.length;
    });
    expect(withRepeat.length).toBe(28);
    // npc 55's hat pool: eleven '0's of 22 entries — "no hat" is EXACTLY 50%.
    const hat = OG_NPCS.find((n) => n.id === 55)?.mcs.hat?.split(',');
    expect(hat?.length).toBe(22);
    expect(hat?.filter((v) => v === '0').length).toBe(11);
  });

  it('FLOATS ARE FLOATS — scale keeps the 2x giant, chance keeps 119 drop rates', () => {
    const scalex = OG_NPCS.map((n) => n.scalex).filter((v): v is number => v !== undefined);
    const scaley = OG_NPCS.map((n) => n.scaley).filter((v): v is number => v !== undefined);
    expect([...new Set([...scalex, ...scaley])].sort((a, b) => a - b)).toEqual([
      0.95, 0.99, 1, 1.1, 1.3, 2,
    ]);
    expect(OG_NPCS.filter((n) => n.scalex === 2).map((n) => n.id)).toEqual([802]);
    const chances = OG_NPCS.flatMap((n) => n.loot ?? []).map((l) => l.chance);
    expect(chances.length).toBe(131);
    expect(chances.filter((c) => !Number.isInteger(c)).length).toBe(119);
    expect([...new Set(chances)].sort((a, b) => a - b)).toEqual([0.05, 0.1, 0.3, 0.4, 0.5, 1]);
  });

  it('LOOT IDS 0-3 ARE A SENTINEL SPACE, not item ids (NPC.as:837-855)', () => {
    const loot = OG_NPCS.flatMap((n) => n.loot ?? []);
    expect([...new Set(loot.map((l) => l.id))].sort((a, b) => a - b)).toEqual([
      0, 1, 2, 3, 2112, 2113, 2114, 20028,
    ]);
    expect([...new Set(loot.map((l) => l.qty))].sort((a, b) => a - b)).toEqual([1, 2, 3, 5]);
  });

  it('`lvl` IS THE NPC\'S OWN — a skill rank never leaks into it', () => {
    // The NPC's level runs 1..80; a skill's rank runs 1..10. If a depth-blind read had
    // put ranks in the level field, the 402 count and this range would both move.
    const lvls = OG_NPCS.map((n) => n.lvl).filter((v): v is number => v !== undefined);
    expect(lvls.length).toBe(402);
    expect(Math.min(...lvls)).toBe(1);
    expect(Math.max(...lvls)).toBe(80);
    const ranks = OG_NPCS.flatMap((n) => n.skills ?? []).map((s) => s.lvl);
    expect(ranks.length).toBe(647);
    expect(Math.min(...ranks)).toBe(1);
    expect(Math.max(...ranks)).toBe(10);
    // 12 rows carry a skill rank and NO level of their own: 402 + 12 = 414 rows
    // contain a <lvl> at some depth, which is the number a depth-blind count returns.
    const skillNoLvl = OG_NPCS.filter((n) => n.lvl === undefined && n.skills !== undefined);
    expect(skillNoLvl.length).toBe(12);
    expect(402 + skillNoLvl.length).toBe(414);
  });

  it('skill ids are 39 distinct values in 1000..1501, all inside the skill table', () => {
    const ids = new Set(OG_NPCS.flatMap((n) => n.skills ?? []).map((s) => s.id));
    expect(ids.size).toBe(39);
    expect(Math.min(...ids)).toBe(1000);
    expect(Math.max(...ids)).toBe(1501);
  });

  it('THE TWO ANOMALIES are preserved verbatim — 356 rows, exactly 2 distinct values', () => {
    expect(OG_NPC_SOURCE_ANOMALIES.length).toBe(356);
    const distinct = [...new Set(OG_NPC_SOURCE_ANOMALIES.map((a) => a.raw))].sort();
    expect(distinct).toEqual(['6.5006501650265E+47', '6015.6017']);
    expect(OG_NPC_SOURCE_ANOMALIES.filter((a) => a.raw === '6015.6017').length).toBe(355);
    const rare = OG_NPC_SOURCE_ANOMALIES.filter((a) => a.raw === '6.5006501650265E+47');
    expect(rare).toEqual([{ npcId: 55, slot: 'hair', raw: '6.5006501650265E+47' }]);
    // Both live in <hair>, and BOTH survive untouched in the row itself — nothing is
    // omitted here (unlike OG_ITEM_SOURCE_ANOMALIES) because slots are strings.
    for (const a of OG_NPC_SOURCE_ANOMALIES) {
      expect(a.slot).toBe('hair');
      const row = OG_NPCS.find((n) => n.id === a.npcId);
      expect(row?.mcs.hair?.split(','), `npc ${String(a.npcId)}`).toContain(a.raw);
    }
    // 6015.6017 is not a typo the transcriber introduced: XMLNpc.as:460 ships it too.
    expect(OG_NPCS.find((n) => n.id === 55)?.mcs.hair).toBe('6.5006501650265E+47');
  });

  it('THE COINCIDENCE TRAP: 5 UNNAMED rows and 6 UNRESOLVED rows are DISJOINT', () => {
    const noTag = OG_NPCS.filter((n) => n.nameId === undefined);
    const unresolved = OG_NPCS.filter((n) => n.nameId !== undefined && n.name === undefined);
    expect(noTag.map((n) => n.id)).toEqual([0, 47, 160, 801, 819]);
    expect(unresolved.map((n) => n.id)).toEqual([50, 51, 52, 53, 54, 55]);
    // All six are the SAME unresolved string id — one broken lookup, not six.
    expect(new Set(unresolved.map((n) => n.nameId))).toEqual(new Set([5017]));
    const noTagIds = new Set(noTag.map((n) => n.id));
    expect(unresolved.filter((n) => noTagIds.has(n.id)).length).toBe(0);
    expect(noTag.length + unresolved.length).toBe(11);
    expect(495 - 11).toBe(484);
  });

  it('THE COINCIDENCE TRAP: the 92 hp-less rows and the 96 skilled rows are DIFFERENT', () => {
    const noHp = OG_NPCS.filter((n) => n.hp === undefined);
    const skilled = OG_NPCS.filter((n) => n.skills !== undefined);
    expect(noHp.length).toBe(92);
    expect(skilled.length).toBe(96);
    const noHpIds = new Set(noHp.map((n) => n.id));
    // Different sizes AND different sets: they overlap on exactly 12 rows, so neither
    // count can be "verified" with the other. Those 12 are not a coincidence either —
    // they are EXACTLY the 12 rows that carry skills and no level of their own, i.e.
    // 12 skilled NPCs with no hp, no lvl, and a full skill list. Measured 2026-09-08.
    const overlap = skilled.filter((n) => noHpIds.has(n.id)).map((n) => n.id);
    expect(overlap).toEqual([161, 164, 181, 182, 187, 188, 190, 191, 197, 809, 810, 811]);
    expect(
      OG_NPCS.filter((n) => n.lvl === undefined && n.skills !== undefined).map((n) => n.id),
    ).toEqual(overlap);
    // npc 55 is the row that carries BOTH the rare anomaly and no hp and no resolved name.
    const n55 = OG_NPCS.find((n) => n.id === 55);
    expect(n55?.hp).toBeUndefined();
    expect(n55?.name).toBeUndefined();
    expect(n55?.nameId).toBe(5017);
  });

  it('every number is finite; only scale and chance may be fractional', () => {
    for (const n of OG_NPCS) {
      for (const [k, v] of Object.entries(n)) {
        if (typeof v !== 'number') continue;
        expect(Number.isFinite(v), `npc ${String(n.id)} ${k}`).toBe(true);
        if (k !== 'scalex' && k !== 'scaley') {
          expect(Number.isInteger(v), `npc ${String(n.id)} ${k} = ${String(v)}`).toBe(true);
        }
      }
      for (const s of n.skills ?? []) {
        expect(Number.isInteger(s.id) && Number.isInteger(s.lvl)).toBe(true);
      }
      for (const l of n.loot ?? []) {
        expect(Number.isInteger(l.id) && Number.isInteger(l.qty)).toBe(true);
        expect(Number.isFinite(l.chance)).toBe(true);
      }
    }
  });
});

/** The byte-check proper — parses the payload with its own independent grammar. */
const NPCDATA = path.join(
  fileURLToPath(new URL('..', import.meta.url)),
  'reference',
  'extracted',
  'npcdata.xml',
);
const HAVE_SOURCE = existsSync(NPCDATA);

/**
 * The closed-vocabulary check, as a pure function so it can be SELF-TESTED. The
 * assertion that caught L2's <req> tree is only worth anything if it still fires.
 */
const tagsIn = (xml: string): string[] =>
  [...new Set([...xml.matchAll(/<(\w+)>/g)].map((m) => m[1] ?? ''))].sort();

const EXPECTED_TAGS = [
  'ai', 'armor', 'attack', 'chance', 'defense', 'earth', 'fire', 'gloves', 'hair',
  'hat', 'head', 'hp', 'id', 'loot', 'lvl', 'mask', 'mcs', 'name', 'neck', 'npc',
  'npcdata', 'pants', 'prop1', 'prop2', 'qty', 'reward', 'scalex', 'scaley', 'shoes',
  'skill', 'skills', 'weapon',
].sort();

describe('L4a-B closed-vocabulary self-test — a disarmed guard must fail loudly', () => {
  it('sees every tag in a well-formed sample', () => {
    expect(
      tagsIn('<npcdata>\r\n<npc>\r\n<id>1</id>\r\n<mcs><hair>6000</hair></mcs>\r\n</npc>\r\n</npcdata>'),
    ).toEqual(['hair', 'id', 'mcs', 'npc', 'npcdata'].sort());
  });

  it('CATCHES an unknown tag — this is the L2 <req> class of failure', () => {
    const injected = '<npcdata><npc><id>1</id><surprise>9</surprise></npc></npcdata>';
    expect(tagsIn(injected)).toContain('surprise');
    expect(tagsIn(injected).every((t) => EXPECTED_TAGS.includes(t))).toBe(false);
  });

  it('the vocabulary is 32 tags and does NOT silently accept an itemdata tag', () => {
    expect(EXPECTED_TAGS.length).toBe(32);
    for (const alien of ['baseprice', 'modifier', 'unique', 'art']) {
      expect(EXPECTED_TAGS).not.toContain(alien);
    }
  });

  it('is CRLF-proof AND bare-LF-proof — npcdata mixes both (9,621 CRLF, 4 bare LF)', () => {
    expect(tagsIn('<npc>\r\n\t<id>1</id>\r\n</npc>')).toEqual(['id', 'npc']);
    expect(tagsIn('<skills>\n<skill><id>1</id><lvl>2</lvl></skill>\n</skills>')).toEqual(
      ['id', 'lvl', 'skill', 'skills'].sort(),
    );
  });
});

describe.skipIf(!HAVE_SOURCE)('L4a-A byte-check — OG_NPCS is a faithful transcription', () => {
  /** Raw-text regex, deliberately NOT the generator's DOM parser. CRLF-aware via \s. */
  const one = (body: string, tag: string): string | undefined => {
    const all = [...body.matchAll(new RegExp(`<${tag}>([\\s\\S]*?)</${tag}>|<${tag}\\s*/>`, 'g'))];
    if (all.length === 0) return undefined;
    if (all.length > 1) throw new Error(`<${tag}> appears ${String(all.length)}x`);
    const trimmed = (all[0]?.[1] ?? '').trim();
    return trimmed === '' ? undefined : trimmed;
  };

  // `describe.skipIf` skips the tests but RUNS this body — guard the read.
  const raw = HAVE_SOURCE ? readFileSync(NPCDATA, 'utf8') : '';
  const blocks = [...raw.matchAll(/<npc>([\s\S]*?)<\/npc>/g)].map((m) => m[1] ?? '');

  it('the source itself holds 495 <npc>, 647 <skill>, 131 <loot> and 3,210 slots', () => {
    expect(blocks.length).toBe(495);
    expect([...raw.matchAll(/<skill>/g)].length).toBe(647);
    expect([...raw.matchAll(/<loot>/g)].length).toBe(131);
    expect([...raw.matchAll(/<skills>/g)].length).toBe(96);
    expect([...raw.matchAll(/<reward>/g)].length).toBe(66);
    const slots = [...raw.matchAll(/<mcs>([\s\S]*?)<\/mcs>/g)].flatMap((m) =>
      [...(m[1] ?? '').matchAll(/<(\w+)>([\s\S]*?)<\/\1>/g)],
    );
    expect(slots.length).toBe(3210);
  });

  it('no source field is silently dropped — the tag vocabulary is CLOSED', () => {
    expect(tagsIn(raw)).toEqual(EXPECTED_TAGS);
  });

  it('the source carries no attributes, and its ONLY empty leaves are 5 <mcs>', () => {
    // Any `<tag attr=...>` form would slip past the vocabulary regex entirely.
    expect(raw.match(/<\w+\s+[^>/]*>/g)).toBeNull();
    const empties = [...raw.matchAll(/<(\w+)>\s*<\/\1>/g)].map((m) => m[1]);
    expect(new Set(empties)).toEqual(new Set(['mcs']));
    expect(empties.length).toBe(5);
  });

  it('every committed NPC matches the source field for field, BY SOURCE ORDER', () => {
    expect(blocks.length).toBe(OG_NPCS.length);
    const anomalies = new Set(
      OG_NPC_SOURCE_ANOMALIES.map((a) => `${String(a.npcId)}|${a.slot}|${a.raw}`),
    );
    let anomaliesSeen = 0;

    blocks.forEach((block, i) => {
      const committed = OG_NPCS[i];
      if (committed === undefined) throw new Error(`no committed npc at index ${String(i)}`);
      const where = `npc index ${String(i)} (id ${String(committed.id)})`;

      // Scalar lookups must see ONLY the NPC's own direct fields. <skills> nests a
      // SECOND <id> AND a second <lvl>; <reward> nests a THIRD <id>. Leaving either in
      // makes `one('id')` throw and would read a skill's rank as the enemy's level.
      const head = block
        .replace(/<skills>[\s\S]*?<\/skills>/g, '')
        .replace(/<reward>[\s\S]*?<\/reward>/g, '')
        .replace(/<mcs>[\s\S]*?<\/mcs>/g, '');

      expect(Number(one(head, 'id')), `${where}: id`).toBe(committed.id);

      const optNum = (tag: string, got: number | undefined): void => {
        const src = one(head, tag);
        expect(src === undefined ? undefined : Number(src), `${where}: ${tag}`).toBe(got);
      };
      optNum('name', committed.nameId);
      optNum('lvl', committed.lvl);
      optNum('hp', committed.hp);
      optNum('ai', committed.ai);
      optNum('attack', committed.attack);
      optNum('defense', committed.defense);
      optNum('scalex', committed.scalex);
      optNum('scaley', committed.scaley);
      optNum('earth', committed.earth);
      optNum('fire', committed.fire);

      // `ai` absent MEANS 1 — XMLNpc.as:135-141, re-derived here from the SOURCE.
      expect(committed.aiEffective, `${where}: aiEffective`).toBe(
        one(head, 'ai') === undefined ? 1 : Number(one(head, 'ai')),
      );

      // <mcs> — ALWAYS present, sometimes EMPTY, and its values are never parsed.
      const mcsAll = [...block.matchAll(/<mcs>([\s\S]*?)<\/mcs>/g)];
      expect(mcsAll.length, `${where}: <mcs> count`).toBe(1);
      const srcSlots = [...(mcsAll[0]?.[1] ?? '').matchAll(/<(\w+)>([\s\S]*?)<\/\1>/g)];
      expect(Object.keys(committed.mcs).length, `${where}: slot count`).toBe(srcSlots.length);
      for (const m of srcSlots) {
        const slot = m[1] ?? '';
        const value = (m[2] ?? '').trim();
        expect(committed.mcs[slot as keyof typeof committed.mcs], `${where}: mcs.${slot}`).toBe(
          value,
        );
        // Fail-closed: every non-integer element MUST also be in the anomaly ledger.
        for (const part of value.split(',')) {
          if (/^-?\d+$/.test(part)) continue;
          anomaliesSeen += 1;
          expect(
            anomalies.has(`${String(committed.id)}|${slot}|${part}`),
            `${where}: mcs.${slot} element ${part} is not in OG_NPC_SOURCE_ANOMALIES`,
          ).toBe(true);
        }
      }

      // <skill> REPEATS — findall, in source order, or the table is a lie.
      const srcSkills = [...block.matchAll(/<skill>([\s\S]*?)<\/skill>/g)].map((m) => m[1] ?? '');
      const gotSkills = committed.skills ?? [];
      expect(srcSkills.length, `${where}: skill count`).toBe(gotSkills.length);
      srcSkills.forEach((s, j) => {
        const row = gotSkills[j];
        if (row === undefined) throw new Error(`${where}: no committed skill ${String(j)}`);
        expect(Number(one(s, 'id')), `${where} skill ${String(j)}: id`).toBe(row.id);
        expect(Number(one(s, 'lvl')), `${where} skill ${String(j)}: lvl`).toBe(row.lvl);
      });

      const srcLoot = [...block.matchAll(/<loot>([\s\S]*?)<\/loot>/g)].map((m) => m[1] ?? '');
      const gotLoot = committed.loot ?? [];
      expect(srcLoot.length, `${where}: loot count`).toBe(gotLoot.length);
      srcLoot.forEach((l, j) => {
        const row = gotLoot[j];
        if (row === undefined) throw new Error(`${where}: no committed loot ${String(j)}`);
        expect(Number(one(l, 'id')), `${where} loot ${String(j)}: id`).toBe(row.id);
        expect(Number(one(l, 'qty')), `${where} loot ${String(j)}: qty`).toBe(row.qty);
        expect(Number(one(l, 'chance')), `${where} loot ${String(j)}: chance`).toBe(row.chance);
      });
    });

    // No fabricated anomalies: the ledger must be exactly what the sweep found.
    expect(anomaliesSeen, 'OG_NPC_SOURCE_ANOMALIES has entries the source does not').toBe(
      OG_NPC_SOURCE_ANOMALIES.length,
    );
  });

  it('the resolved names come from the string table, not from the transcriber', () => {
    const names = JSON.parse(
      readFileSync(
        path.join(
          fileURLToPath(new URL('..', import.meta.url)),
          'docs', 'gauntlet', 'L0', 'index', 'resolved_names.json',
        ),
        'utf8',
      ),
    ) as { 'npcdata.xml': { resolved: Record<string, { name?: string }>; misses: number } };
    const resolved = names['npcdata.xml'].resolved;
    expect(Object.keys(resolved).length).toBe(484);
    expect(names['npcdata.xml'].misses).toBe(6);
    for (const npc of OG_NPCS) {
      expect(npc.name, `npc ${String(npc.id)}: name`).toBe(resolved[String(npc.id)]?.name);
    }
  });
});
